parameters.text:
Eres un extractor de datos para FrontierAdvice Chile.

Usa la herramienta MCP Playwright para abrir https://x.com/UPFronterizos y leer los últimos 8 posts visibles sin iniciar sesión.

Debes devolver exclusivamente JSON válido con esta estructura:

{
  "items": [
    {
      "codigo_fuente": "los-libertadores",
      "nombre_detectado": "Paso Los Libertadores",
      "estado_general": "cerrado",
      "mensaje_original": "texto del post",
      "fecha_reporte": "2026-05-29T00:00:00Z",
      "confianza_extraccion": 0.92,
      "restricciones": [
        {
          "tipo_restriccion": "clima_nieve",
          "descripcion": "Cierre por nevadas"
        }
      ],
      "alertas": [
        {
          "tipo_alerta": "evento_climatico",
          "descripcion": "Nevadas en alta montaña",
          "fuente": "x_upfronterizos"
        }
      ]
    }
  ]
}

Reglas:
- Ignora posts que no hablen del estado de pasos fronterizos.
- No inventes datos.
- estado_general solo puede ser: habilitado, cerrado, habilitado_con_precaucion, demora, sin_informacion.
- codigo_fuente debe ir en kebab-case.
- Si no logras detectar fecha exacta, usa la fecha actual de ejecución.
- Devuelve solo JSON, sin markdown ni texto adicional.

parameters.jsCode:
const raw = $json.output || $json.text || $json.response || $json.data || $json;
let parsed = raw;

if (typeof raw === 'string') {
  const cleaned = raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  parsed = JSON.parse(cleaned);
}

if (!parsed.items || !Array.isArray(parsed.items)) {
  throw new Error('El agente no devolvió items[]. Output recibido: ' + JSON.stringify(raw).substring(0, 500));
}

return parsed.items.map(item => ({
  json: {
    codigo_fuente: item.codigo_fuente || null,
    nombre_detectado: item.nombre_detectado || null,
    estado_general: item.estado_general || 'sin_informacion',
    mensaje_original: item.mensaje_original || '',
    fecha_reporte: item.fecha_reporte || new Date().toISOString(),
    confianza_extraccion: item.confianza_extraccion ?? 0.5,
    fuente: 'x_upfronterizos',
    restricciones: Array.isArray(item.restricciones) ? item.restricciones : [],
    alertas: Array.isArray(item.alertas) ? item.alertas : [],
  }
}));;

return [
  {
    json: {
      source_id: $json.source_id,
      source_type: $json.source_type,
      source_name: $json.source_name,
      channel_label: $json.channel_label,
      captured_at: $json.captured_at,
      max_messages: $json.max_messages,
      extract_mode: "latest_messages"
    }
  }
];

return [
  {
    json: {
      source_id: $json.source_id,
      source_type: $json.source_type,
      source_name: $json.source_name,
      channel_label: $json.channel_label,
      captured_at: $json.captured_at,
      messages: [
        "Complejo Los Libertadores cerrado preventivamente por nevadas y bajas temperaturas.",
        "Paso Pehuenche habilitado con precaución para vehículos menores.",
        "Cardenal Samoré opera con normalidad en ambos sentidos.",
        "Se recomienda revisar estado meteorológico antes de viajar.",
        "Horarios diferenciados para transporte de carga en algunos complejos."
      ]
    }
  }
];

const raw =
  $json.text ??
  $json.output ??
  $json.response ??
  $json.result ??
  $json.message ??
  $json.content ??
  $json;

let parsed;
let cleaned = raw;

if (typeof cleaned === "string") {
  cleaned = cleaned.replace(/```json\s*/g, "").replace(/```/g, "").trim();

  const start = cleaned.indexOf("{");
  const end = cleaned.lastIndexOf("}");
  if (start !== -1 && end !== -1) {
    cleaned = cleaned.slice(start, end + 1);
  }

  parsed = JSON.parse(cleaned);
} else {
  parsed = cleaned;
}

if (!parsed || !parsed.items || !Array.isArray(parsed.items)) {
  throw new Error("No se encontró items[] en la salida del modelo. Output recibido: " + JSON.stringify($json).slice(0, 1000));
}

return parsed.items.map(item => ({
  json: {
    codigo_fuente: item.codigo_fuente || null,
    fecha_reporte: item.fecha_reporte || $("Set Source Metadata").first().json.captured_at,
    estado_general: item.estado_general || "desconocido",
    fuente: item.fuente || "whatsapp_upf",
    mensaje_original: item.mensaje_original || null,
    confianza_extraccion: item.confianza_extraccion ?? 0.5,
    origen_tipo: item.origen_tipo || "whatsapp_channel"
  }
}));

const pasoResp = $json.data || [];
if (!pasoResp.length) {
  throw new Error("No se encontró PasoFronterizo para codigo_fuente");
}

const paso = pasoResp[0];

const original = $("Parse Model Output").item.json;

return [
  {
    json: {
      data: {
        fecha_reporte: original.fecha_reporte,
        estado_general: original.estado_general,
        fuente: original.fuente,
        mensaje_original: original.mensaje_original,
        confianza_extraccion: String(original.confianza_extraccion),
        origen_tipo: original.origen_tipo,
        id_paso: paso.id
      }
    }
  }
];
